export const mailMigrations: readonly Migration[] = [
  {
    filename: "0001_init.sql",
    checksum: "sha256-c5bb49ea4706dc4d402f9fb635719a6b340b4270fd8541cdc4786bad5f43bb66",
    sql: "-- mail / citizenry — D1 (SQLite) initial schema.\n--\n-- Conventions:\n--   - TEXT identifiers with ULID prefix (mb_, mai_, att_, thr_)\n--   - INTEGER timestamps (unixepoch() * 1000) — ms since epoch\n--   - JSON-encoded address lists and keyword sets, stored as TEXT\n--   - BLOB column for attachment bytes (D1 row-size bound; large\n--     attachments are out of scope for v1)\n\n\n-- ── mailbox ─────────────────────────────────────────────────\n-- Named folders owned by an agent. role = JMAP well-known role\n-- (RFC 8621 §2) or NULL for custom mailboxes.\nCREATE TABLE IF NOT EXISTS mailbox (\n    mailbox_id      TEXT    NOT NULL,\n    account_id      TEXT    NOT NULL,\n    name            TEXT    NOT NULL,\n    role            TEXT,\n    total_mails     INTEGER NOT NULL DEFAULT 0,\n    unread_mails    INTEGER NOT NULL DEFAULT 0,\n    created_at      INTEGER NOT NULL DEFAULT (unixepoch() * 1000),\n\n    CONSTRAINT mailbox_pkey      PRIMARY KEY (mailbox_id),\n    CONSTRAINT mailbox_role_check\n        CHECK (role IS NULL OR role IN ('inbox','sent','drafts','archive','trash','junk'))\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS mailbox_account_name_uniq\n    ON mailbox (account_id, name);\nCREATE INDEX IF NOT EXISTS mailbox_account_idx\n    ON mailbox (account_id);\n\n\n-- ── mail ───────────────────────────────────────────────────\n-- One row per message (inbound or outbound).\nCREATE TABLE IF NOT EXISTS mail (\n    mail_id               TEXT    NOT NULL,\n    account_id            TEXT    NOT NULL,\n    mailbox_id            TEXT    NOT NULL,\n\n    thread_id             TEXT    NOT NULL,\n    message_id            TEXT,\n    in_reply_to           TEXT,\n    refs                  TEXT    NOT NULL DEFAULT '[]',\n\n    subject               TEXT,\n    preview               TEXT,\n    body_text             TEXT,\n    body_html             TEXT,\n\n    from_addr             TEXT,\n    to_addrs              TEXT    NOT NULL DEFAULT '[]',\n    cc_addrs              TEXT    NOT NULL DEFAULT '[]',\n    bcc_addrs             TEXT    NOT NULL DEFAULT '[]',\n    reply_to_addrs        TEXT    NOT NULL DEFAULT '[]',\n\n    keywords              TEXT    NOT NULL DEFAULT '{}',\n    size                  INTEGER NOT NULL DEFAULT 0,\n    has_attachment        INTEGER NOT NULL DEFAULT 0,\n\n    received_at           INTEGER NOT NULL,\n    sent_at               INTEGER,\n\n    direction             TEXT    NOT NULL,\n    delivery_status       TEXT    NOT NULL,\n    delivery_error        TEXT,\n    provider_message_id   TEXT,\n\n    created_at            INTEGER NOT NULL DEFAULT (unixepoch() * 1000),\n\n    CONSTRAINT mail_pkey                  PRIMARY KEY (mail_id),\n    CONSTRAINT mail_mailbox_fk            FOREIGN KEY (mailbox_id)\n        REFERENCES mailbox (mailbox_id) ON DELETE CASCADE,\n    CONSTRAINT mail_direction_check       CHECK (direction IN ('inbound','outbound')),\n    CONSTRAINT mail_delivery_status_check\n        CHECK (delivery_status IN ('received','queued','sent','failed'))\n);\n\nCREATE INDEX IF NOT EXISTS mail_account_idx\n    ON mail (account_id);\nCREATE INDEX IF NOT EXISTS mail_mailbox_received_idx\n    ON mail (mailbox_id, received_at);\nCREATE INDEX IF NOT EXISTS mail_thread_idx\n    ON mail (account_id, thread_id);\nCREATE INDEX IF NOT EXISTS mail_message_id_idx\n    ON mail (message_id);\n\n\n-- ── mail_attachment ────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS mail_attachment (\n    attachment_id    TEXT    NOT NULL,\n    mail_id          TEXT    NOT NULL,\n    filename         TEXT,\n    content_type     TEXT    NOT NULL,\n    size             INTEGER NOT NULL,\n    cid              TEXT,\n    inline           INTEGER NOT NULL DEFAULT 0,\n    blob             BLOB    NOT NULL,\n\n    CONSTRAINT mail_attachment_pkey     PRIMARY KEY (attachment_id),\n    CONSTRAINT mail_attachment_mail_fk  FOREIGN KEY (mail_id)\n        REFERENCES mail (mail_id) ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS mail_attachment_mail_idx\n    ON mail_attachment (mail_id);\n",
  },
  {
    filename: "0002_add_inbound_log.sql",
    checksum: "sha256-e9b4d28a2864dea766a63f7da6c57bb76860fca9afd09c32995447c3ff8fe187",
    sql: "-- mail / citizenry — inbound audit log.\n--\n-- Every Cloudflare Email Worker invocation writes one row here, even\n-- when the message is rejected or dropped. Lets operators verify that\n-- mail is actually arriving and diagnose silent-drop paths\n-- (agent slug not found, wrong host, parse failure, etc.) without\n-- relying on Worker logs alone.\n--\n-- Successful inbound goes here AND into `mail` — `mail_id` cross-refs\n-- the stored row. Dropped messages get `mail_id IS NULL` and a\n-- `disposition` value that explains why.\n\nCREATE TABLE IF NOT EXISTS mail_inbound_log (\n    inbound_log_id   TEXT    NOT NULL,\n    received_at      INTEGER NOT NULL DEFAULT (unixepoch() * 1000),\n    rcpt_to          TEXT    NOT NULL,\n    mail_from        TEXT,\n    raw_size         INTEGER,\n\n    -- One of:\n    --   'stored'                 — persisted to `mail` (mail_id is set)\n    --   'duplicate'              — Message-ID already stored (mail_id is set)\n    --   'malformed_recipient'    — rcpt_to has no '@'\n    --   'wrong_host'             — host part not MAIL_DOMAIN\n    --   'unresolved_recipient'   — no agent.slug matches local-part\n    --   'parse_failed'           — postal-mime threw\n    --   'store_failed'           — INSERT into mail threw\n    disposition      TEXT    NOT NULL,\n\n    -- Populated when the local-part resolved to an agent.\n    account_id       TEXT,\n    -- Populated when the row landed in `mail`.\n    mail_id          TEXT,\n    -- RFC 5322 Message-ID, when parsing succeeded.\n    message_id       TEXT,\n    -- Free-form failure detail when disposition indicates an error.\n    error_message    TEXT,\n\n    CONSTRAINT mail_inbound_log_pkey   PRIMARY KEY (inbound_log_id),\n    CONSTRAINT mail_inbound_log_disposition_check CHECK (disposition IN (\n        'stored',\n        'duplicate',\n        'malformed_recipient',\n        'wrong_host',\n        'unresolved_recipient',\n        'parse_failed',\n        'store_failed'\n    ))\n);\n\nCREATE INDEX IF NOT EXISTS mail_inbound_log_received_idx\n    ON mail_inbound_log (received_at DESC);\nCREATE INDEX IF NOT EXISTS mail_inbound_log_rcpt_to_idx\n    ON mail_inbound_log (rcpt_to);\nCREATE INDEX IF NOT EXISTS mail_inbound_log_disposition_idx\n    ON mail_inbound_log (disposition);\n",
  },
  {
    filename: "0003_add_outbound_log.sql",
    checksum: "sha256-d78eda9276c1a25edf7a9758c1cd9bc1914b3d2a477b4beb5c8eb12531fa0283",
    sql: "-- mail / citizenry — outbound audit log.\n--\n-- Sibling of mail_inbound_log: every system-initiated send through\n-- POST /_internal/notify writes one row here. Agent-initiated sends\n-- (POST /mails with agent JWT) also flow through the same sender\n-- pipeline; whether to log those here too is left for a follow-up —\n-- this migration only commits the table shape.\n--\n-- See ADR-2026-0005 for the centralize-outbound-through-mail decision.\n\nCREATE TABLE IF NOT EXISTS mail_outbound_log (\n    outbound_log_id      TEXT    NOT NULL,\n    requested_at         INTEGER NOT NULL DEFAULT (unixepoch() * 1000),\n\n    -- Calling Worker (`citizenry-api`, `citizenry-admin-api`, ...).\n    -- Best-effort: derived from the X-Caller header when present,\n    -- otherwise NULL.\n    caller               TEXT,\n\n    -- Template key the caller requested (e.g. `human_verification`).\n    template             TEXT    NOT NULL,\n\n    -- JSON array of `[{ \"name\": \"...\", \"mail\": \"...\" }, ...]`.\n    to_addrs             TEXT    NOT NULL DEFAULT '[]',\n    -- Sender envelope address used (may be the per-instance default).\n    from_addr            TEXT,\n\n    -- One of: 'queued' | 'sent' | 'failed' | 'invalid_request'.\n    status               TEXT    NOT NULL,\n    -- Provider message id when status='sent' and provider returns one.\n    provider_message_id  TEXT,\n    -- Sender chosen by pickSender at request time\n    -- (`cloudflare` / `resend` / `aws-ses` / `log-only`).\n    sender_name          TEXT,\n    -- Failure detail when status='failed' or 'invalid_request'.\n    error_message        TEXT,\n\n    CONSTRAINT mail_outbound_log_pkey PRIMARY KEY (outbound_log_id),\n    CONSTRAINT mail_outbound_log_status_check\n        CHECK (status IN ('queued','sent','failed','invalid_request'))\n);\n\nCREATE INDEX IF NOT EXISTS mail_outbound_log_requested_idx\n    ON mail_outbound_log (requested_at DESC);\nCREATE INDEX IF NOT EXISTS mail_outbound_log_template_idx\n    ON mail_outbound_log (template);\nCREATE INDEX IF NOT EXISTS mail_outbound_log_status_idx\n    ON mail_outbound_log (status);\n",
  },
] as const

export const configMigrations: readonly Migration[] = [
  {
    filename: "0001_init.sql",
    checksum: "sha256-ff5f83ffe09573478ed45afa08816f5bfcc8050f03393d0e01d01e84be0c687b",
    sql: "-- config / citizenry — D1 (SQLite) initial schema.\n--\n-- A small key/value store used as the runtime control plane for the\n-- citizenry deployment. Writes go through admin-api → api `/_admin/*`;\n-- reads come from packages/identity and packages/mail (via a\n-- colo-local TTL cache layered on top of packages/config).\n--\n-- Conventions:\n--   - `config_key` is the natural primary key. Dot-separated namespace\n--     by convention (e.g. `mail.provider`, `identity.signing.kid`).\n--   - `config_value` is a JSON-encoded scalar/object. The reader parses\n--     and the writer stringifies; the column is opaque to D1.\n--   - `updated_at` is INTEGER ms since epoch (unixepoch() * 1000),\n--     matching the rest of the schema.\n--   - `updated_by` records the principal that performed the write —\n--     typically `hu_<ULID>` from the admin-api request, or `system`\n--     for bootstrap writes from CI.\n\nCREATE TABLE IF NOT EXISTS config (\n    config_key   TEXT    NOT NULL,\n    config_value TEXT    NOT NULL,\n    updated_at   INTEGER NOT NULL DEFAULT (unixepoch() * 1000),\n    updated_by   TEXT,\n\n    CONSTRAINT config_pkey PRIMARY KEY (config_key)\n);\n\nCREATE INDEX IF NOT EXISTS config_updated_at_idx ON config (updated_at);\n",
  },
  {
    filename: "0002_add_config_id.sql",
    checksum: "sha256-5b4435a637591174c76bf16842db3f1d46a5c08fba22b9fd9c0de99c33f95817",
    sql: "-- config / citizenry — reshape from (config_key PK) to (config_id PK + config_key UNIQUE).\n--\n-- Why: the public CRUD surface keys rows by `config_key`, but every\n-- other domain table in this codebase carries an explicit `<table>_id`\n-- ULID column. Adding it now keeps the storage layout consistent and\n-- gives admin tooling a stable identifier independent of the\n-- human-chosen key string.\n--\n-- This is a non-destructive migration when the table is empty:\n-- 0001 was deployed but no production traffic has written to it yet,\n-- so a drop-and-recreate is the safest path (SQLite cannot rewrite a\n-- PRIMARY KEY in place). If a deployment has accumulated rows by the\n-- time this lands, the operator must export them before applying and\n-- re-import after.\n\nDROP TABLE IF EXISTS config;\n\nCREATE TABLE IF NOT EXISTS config (\n    config_id    TEXT    NOT NULL,\n    config_key   TEXT    NOT NULL,\n    config_value TEXT    NOT NULL,\n    updated_at   INTEGER NOT NULL DEFAULT (unixepoch() * 1000),\n    updated_by   TEXT,\n\n    CONSTRAINT config_pkey      PRIMARY KEY (config_id),\n    CONSTRAINT config_key_uniq  UNIQUE (config_key)\n);\n\nCREATE INDEX IF NOT EXISTS config_updated_at_idx ON config (updated_at);\n",
  },
] as const
